mapper.select:
SELECT id,symbol,JSON_UNQUOTE(JSON_EXTRACT(snapshot_json,'$.research.name')) AS name,horizon,action_code,archived,created_at,
research_date AS as_of, NULL AS latest_review_date, NULL AS latest_review_status, NULL AS latest_review_explanation, FALSE AS acknowledged, acknowledged_review_hash, JSON_UNQUOTE(JSON_EXTRACT(snapshot_json,'$.research.source')) AS source, NULL AS input_sources
FROM research_plan  ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

SELECT id,plan_id,review_json,review_hash,created_at FROM (
SELECT r.*,ROW_NUMBER() OVER(PARTITION BY plan_id ORDER BY review_date DESC,id DESC) AS review_rank
FROM research_plan_review r
WHERE plan_id IN #{id}
AND review_date <= #{asOf}
AND JSON_UNQUOTE(JSON_EXTRACT(review_json, '$.status'))=#{status}
) ranked WHERE review_rank=1
